}

SELECT ?z ?label ?cls WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
} LIMIT 50

SELECT ?pt ?cls ?ts WHERE {
  ?pt a brick:OccupancySensor .
  OPTIONAL { ?pt ref:hasTimeseriesId ?ts }
  ?pt brick:isPartOf ?z .
  ?z rdfs:label ?cls .
} LIMIT 50

